SELECT , 
       ci.class_name, co.course_name, u.real_name as creator_name
FROM class_activity a
LEFT JOIN class_info ci ON a.class_id = ci.id
LEFT JOIN course co ON a.course_id = co.id
LEFT JOIN sys_user u ON a.creator_id = u.id


